('1585','baza_velebit_2026_apk_sync','Ključanica',44.7618420504271,14.9937401393403,'u_katastru','HR02047','u_katastru','jama','Ličko-senjska','Senj','Krasno','Rožanski kukovi',112.5,161.3,null,'u_katastru','{"id": "1585", "source": "sov", "source_labels": ["sov"], "name": "Ključanica", "location": {"lat": 44.7618420504271, "lon": 14.9937401393403, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Rožanski kukovi", "island": null, "altitude_m": 1532.0, "protected_area": null}, "cadastre": {"status": "u_katastru", "cadastral_number": "HR02047", "in_cadastre": true, "not_in_cadastre_candidate": null}, "classification": {"object_type": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "record_status": "u_katastru", "field_tasks": [], "priority": null, "kml_export_candidate": true}, "metrics": {"depth_m": 112.5, "length_m": 161.3, "vertical_range_m": 112.5, "entrance_count": 1}, "condition": {"plate_number": "05-796", "main_entrance_status": null, "hazards": "lažno dno; led;", "pollution": null}, "research": {"last_research_year": 2017, "last_research_date": "30.7.-1.8.2017.", "clubs": "SOV", "team_members": "Matija Čepelak; Marijan Sutlović; Domagoj Čajko", "survey_author": "2017:Marijan Sutlović", "survey_in_digital_base": true, "bibliography_record": null, "georef_record": null, "further_research_possible": null, "further_research_note": "nastavak istraživanja je moguć u slučaju topljenje ledenog čepa"}, "content": {"access_description": "Premužićevom stazom iz smjera V. Alana prema Crikveni. Netom prije uspona staze prema Crikveni skreće se desno (E) sa staze u šumu. Kroz šumu se kreće blago nizbrdo u smjeru J - I do livadice na rubu vrtače. Po izohipsi se kreće uz južnu i istočnu stranu vrtače te se pređe greben u uđe u slijedeću vrtaču koja je sjeveno od prve. Ulaz se nalazi pri vrhu vrtače na rubu gdje šuma prelazi u stijene, JZ dio vrtače.", "technical_description": "Ulazna vertikala se završava na ledu, led se pojavljuje pri dubini od oko 75 m. S ulaznom vertikalom je paralelna druga koje se spajaju na otprilike 60 m dubine. Jama je u gornjem dijelu postavljena spitevima, a u donjim fixevima.", "note": "Topljenjem leda jama postaje perspektivna", "literature": null, "name_origin": null, "synonyms": "0", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),true,'05-796','da',null,null,null),
('1586','baza_velebit_2026_apk_sync','(Ne)radni disto',44.7651954027326,15.0244890472055,'krug_14',null,'na_provjeri','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi, Sjeverni Velebit',11.3,12.3,null,'na_provjeri','{"id": "1586", "source": "sov", "source_labels": ["sov"], "name": "(Ne)radni disto", "location": {"lat": 44.7651954027326, "lon": 15.0244890472055, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi, Sjeverni Velebit", "island": null, "altitude_m": 1520.0, "protected_area": null}, "cadastre": {"status": "krug_14", "cadastral_number": null, "in_cadastre": false, "not_in_cadastre_candidate": null}, "classification": {"object_type": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "record_status": "na_provjeri", "field_tasks": [], "priority": null, "kml_export_candidate": true}, "metrics": {"depth_m": 11.3, "length_m": 12.3, "vertical_range_m": 11.3, "entrance_count": 1}, "condition": {"plate_number": "05-1247", "main_entrance_status": null, "hazards": "nema", "pollution": "nema"}, "research": {"last_research_year": 2025, "last_research_date": "4.8.2025", "clubs": "SOV, SOM", "team_members": "Mia Šepčević, Dario Mrkonjić, Marko Batovanja, Mislav Sajko, Lea Okićki", "survey_author": "Mia Šepčević", "survey_in_digital_base": true, "bibliography_record": null, "georef_record": "103491;Jama 308;383196.6554625675;4959409.85014434;0.7071067811865476", "further_research_possible": null, "further_research_note": "potpuno istražen"}, "content": {"access_description": "Jama se nalazi u Hajdučkim kukovima na sjevernom Velebitu. U Krasnom se krene glavnom šumskom asfaltiranom cestom prema Velikom Lomu. Dolazi se do raskrižja koje je na oštrom zavoju i skrene se desno u smjeru Zavižana. Na ovom raskrižju se skreće s asfaltirane ceste na makadam koji vodi do Zavižana te je postavljena rampa na ulazu u makadam. Nakon cca 4 km skrene se u lijevo u šumu (smjer JZ) odnosno prate se oznake koje su postavili speleolozi za put prema Lukinoj jami. Nakon ulaza u Trojamu kretati se još cca 200 metara u smjeru jugozapada.", "technical_description": "Jednostavan vertikalni objekt opremljen s dva sidrišta. Potrebna oprema: uže 30m, 3 pločice, bužir", "note": null, "literature": null, "name_origin": "smišljeno novo", "synonyms": "Jama 308", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1247','da',null,null,'103491;Jama 308;383196.6554625675;4959409.85014434;0.7071067811865476'),
