('1596','baza_velebit_2026_apk_sync','Jamica s pogledom na Velikom Rajincu',44.7762971927215,15.0339857699813,'krug_14',null,'na_provjeri','špilja s jamskim ulazom','Ličko-senjska','Senj','Krasno','Veliki Rajinac, Sjeverni Velebit',7.0,11.5,null,'na_provjeri','{"id": "1596", "source": "sov", "source_labels": ["sov"], "name": "Jamica s pogledom na Velikom Rajincu", "location": {"lat": 44.7762971927215, "lon": 15.0339857699813, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Veliki Rajinac, Sjeverni Velebit", "island": null, "altitude_m": 1442.0, "protected_area": null}, "cadastre": {"status": "krug_14", "cadastral_number": null, "in_cadastre": false, "not_in_cadastre_candidate": null}, "classification": {"object_type": "špilja s jamskim ulazom", "object_type_source": "kml_sjeverni_velebit_2026", "record_status": "na_provjeri", "field_tasks": [], "priority": null, "kml_export_candidate": true}, "metrics": {"depth_m": 7.0, "length_m": 11.5, "vertical_range_m": 7.0, "entrance_count": 2}, "condition": {"plate_number": "05-1179", "main_entrance_status": null, "hazards": "nema", "pollution": "nema"}, "research": {"last_research_year": 2025, "last_research_date": "31.7.2025", "clubs": "SOV", "team_members": "Ema Buljan, Dragana Rajković, Dalibor Paar", "survey_author": "Ema Buljan", "survey_in_digital_base": true, "bibliography_record": null, "georef_record": "321011;Jamica s pogledom na Velikom Rajincu;383971.9999999338;4960633.999999907;0.7071067811865476", "further_research_possible": null, "further_research_note": "potpuno istražen"}, "content": {"access_description": "Špilja se nalazi u Lomskoj dulibi na Sjevernom Velebitu na zapadnom obronku Velikog Rajinca. Na makadamskoj cesti auto se parkira između Roguša i Lekčevca na vidljivom ugibalištu sa strane. Krene se u dulibu prema Ledenoj jami, ali umjesto prema jami skrene se blago udesno prema brdu. Na najlakšem dijelu skrene se s travnjaka prema šumi. Potrebno je popeti se 190 m nadmorske visine prateći koordinate. Špilja se nalazi nešto dalje od Mjesečevog meandra, blizu goli stijena s kojih se pruža lijep pogledm prema Hajdučkim kukovima. Ulaz je vidljiv tek iz blizine.", "technical_description": "Ulaz se nalazi na manjem platou masivne stijene s koje se vide Hajdučki kukovi. Desno od ulaza je stijena visine 5 m. Ulaz se spušta usko i na samom ulazu je skok od 3 m za kojeg nije potrebna oprema. Špiljski kanal se strmo spušta i prekriven je lišćem i humusom i dolazi se do dna odakle se proteže niz špranjica dubine 2 m. Na dnu se vidi vanjsko svjetlo.", "note": "jama je imala oznaku A1", "literature": null, "name_origin": "smišljeno novo", "synonyms": "A1", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1179','da',null,null,'321011;Jamica s pogledom na Velikom Rajincu;383971.9999999338;4960633.999999907;0.7071067811865476'),
