o koje je zaglonđano i ima nekoliko dijagonalno položenih balvana. Za ući u objekt potrebno je 20 m užeta, 2 sidrišna kompleta, gurtna i bužir.", "note": null, "literature": null, "name_origin": "smišljeno novo", "synonyms": "LiVEL 111", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1177','da',null,null,'321037;Kilava sarma;385029.9999999369;4958970.9999999115;0.7071067811865476'),
