('1604','baza_velebit_2026_apk_sync','La Jama desnuda',44.7592799893516,15.0090400261972,'krug_14',null,'na_provjeri','jama','Ličko-senjska','Senj','Krasno','Dulibice, Rožanski kukovi, Sjeverni Velebit',56.0,126.0,null,'na_provjeri','{"id": "1604", "source": "sov", "source_labels": ["sov"], "name": "La Jama desnuda", "location": {"lat": 44.7592799893516, "lon": 15.0090400261972, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Dulibice, Rožanski kukovi, Sjeverni Velebit", "island": null, "altitude_m": 1395.0, "protected_area": null}, "cadastre": {"status": "krug_14", "cadastral_number": null, "in_cadastre": false, "not_in_cadastre_candidate": null}, "classification": {"object_type": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "record_status": "na_provjeri", "field_tasks": [], "priority": null, "kml_export_candidate": true}, "metrics": {"depth_m": 56.0, "length_m": 126.0, "vertical_range_m": 56.0, "entrance_count": 2}, "condition": {"plate_number": "05-1183", "main_entrance_status": null, "hazards": "led", "pollution": "nema"}, "research": {"last_research_year": 2025, "last_research_date": "1.8.2025", "clubs": "SOV, SUE", "team_members": "Dora Troha, Olga Jerković Perić, Luka Peloza, Venio Fabijančić, Toni Kočevar", "survey_author": "Olga Jerković Perić", "survey_in_digital_base": true, "bibliography_record": null, "georef_record": "321043;La Jama desnuda;381962.99999992765;4958778.999999898;0.7071067811865476", "further_research_possible": null, "further_research_note": "nastavlja se spuštanjem, nastavlja se provlačenjem, moguć nastavak u slučaju topljenja ledenog čepa"}, "content": {"access_description": "Jama se nalazi na istočnoj strani Rožanskih kukova južno od Lubenovačkih vrata. 70 m visinski od makadamskog puta koji vodi od Velikog Lubenovca. Makadamskim putem od Velikog Lubenovca krenuti prema Luenovačkim vratima 1300 m i onda skrenuti na JZ i hodati na JZ. Pristup je težak, mnogo je srušeni stabala.", "technical_description": "Objekt ima dva vertikalna ulaza. Prvi, veći ulaz ima na polici na 20 m snijeg i led koji se nastavlja do trenutnog dna. Kroz pukotinu cca 70 cm izeđu leda i stijene od ulaza sa početnog sidrišta preko stijene ide dvostruko sidrište te onda nakon 10-15m međusidrište i onda ulazimo u pukotinu i onda idu 3 sidrišta do spoja s drugom vertikalom. Dno završava manjim prolazom. Druga vertikala je opasna zbog ledeni zavjesa, snijega, glonđi koje se mogu urušiti.", "note": "led, mogućnost urušavanja velikih ledenih siga, drveća i kamenja zarobljenih u ledu", "literature": null, "name_origin": "smišljeno novo", "synonyms": "Pali libido", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1183','da',null,null,'321043;La Jama desnuda;381962.99999992765;4958778.999999898;0.7071067811865476'),
('1605','baza_velebit_2026_apk_sync','Ledeno gnijezdo',44.7998467386517,14.9923469588618,'krug_14',null,'na_provjeri','jama','Ličko-senjska','Senj','Krasno','Veliki Pivčevac, Sjeverni Velebit',21.5,26.5,null,'na_provjeri','{"id": "1605", "source": "sov", "source_labels": ["sov"], "name": "Ledeno gnijezdo", "location": {"lat": 44.7998467386517, "lon": 14.9923469588618, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Veliki Pivčevac, Sjeverni Velebit", "island": null, "altitude_m": 1481.0, "protected_area": null}, "cadastre": {"status": "krug_14", "cadastral_number": null, "in_cadastre": false, "not_in_cadastre_candidate": null}, "classification": {"object_type": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "record_status": "na_provjeri", "field_tasks": [], "priority": null, "kml_export_candidate": true}, "metrics": {"depth_m": 21.5, "length_m": 26.5, "vertical_range_m": 21.5, "entrance_count": 1}, "condition": {"plate_number": "05-1187", "main_entrance_status": null, "hazards": "led", "pollution": "nema"}, "research": {"last_research_year": 2025, "last_research_date": "31.7.2025", "clubs": "SOV, Osmica, SOM", "team_members": "Nino Pintarić, Rene Borna Gržin, Igor Jelinić, Dario Mrkonjić, Jelena Zovko, Paula Skelin", "survey_author": "Dario Mrkonjić", "survey_in_digital_base": true, "bibliography_record": null, "georef_record": "321044;Ledeno gnijezdo;380724.9999999237;4963310.999999889;0.7071067811865476", "further_research_possible": null, "further_research_note": "potpuno istražen"}, "content": {"access_description": "Jama se nalazi na južnim obroncima Velikog Pivčevca na sjevernom Velebitu. Ići makadamskom cestom od Lomske Dulibe za Zavižan, produžiti nakon skretanja za Škrbinu Dragu. Na drugom serpentinskom zavoju parkirati te produžiti prema sjeveru šumskom vlakom cca 250 m te potom skrenuti prema istoku u prvu vrtaču.", "technical_description": "Jednostavni vertikalni objekt; ulaz je razdijeljen na 2 otvora međusobno odvojena kamenim mostom. Jama je zatrpana snijegom i ledom te se na južnoj strani (dnu ledene kosine) otvara manji procjep koji se zavlači cca 6 m ispod nanosa snijega i leda. Nema značajnog strujanja zraka te ni perspektive za daljnje istraživanje.", "note": "WGS koordinate: 44.799847, 14.992347", "literature": null, "name_origin": "smišljeno novo", "synonyms": "LiVEL 178", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1187','da',null,null,'321044;Ledeno gnijezdo;380724.9999999237;4963310.999999889;0.7071067811865476'),
