port": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1209','da',null,null,'321045;Lojtrica;380493.99999992293;4954060.99999989;0.7071067811865476'),
('1607','baza_velebit_2026_apk_sync','Magični portal',44.7247943950958,15.0049777841174,'krug_14',null,'na_provjeri','špilja','Ličko-senjska','Senj','Jablanac','Golići, Sjeverni Velebit',12.0,27.0,null,'na_provjeri','{"id": "1607", "source": "sov", "source_labels": ["sov"], "name": "Magični portal", "location": {"lat": 44.7247943950958, "lon": 15.0049777841174, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Jablanac", "locality": "Golići, Sjeverni Velebit", "island": null, "altitude_m": 1570.0, "protected_area": null}, "cadastre": {"status": "krug_14", "cadastral_number": null, "in_cadastre": false, "not_in_cadastre_candidate": null}, "classification": {"object_type": "špilja", "object_type_source": "kml_sjeverni_velebit_2026", "record_status": "na_provjeri", "field_tasks": [], "priority": null, "kml_export_candidate": true}, "metrics": {"depth_m": 12.0, "length_m": 27.0, "vertical_range_m": 12.0, "entrance_count": 1}, "condition": {"plate_number": "05-1026", "main_entrance_status": null, "hazards": "nema", "pollution": "nema"}, "research": {"last_research_year": 2025, "last_research_date": "7.8.2025", "clubs": "SOV, V.f.H. Höhlenbären", "team_members": "Olga Jerković Perić, Jakov Rešetar, Filip Eichler", "survey_author": "Olga Jerković Perić", "survey_in_digital_base": true, "bibliography_record": null, "georef_record": "321046;Magični portal;381570.9999999264;4954952.999999895;0.7071067811865476", "further_research_possible": null, "further_research_note": "potpuno istražen"}, "content": {"access_description": "Špilja se nalazi sa južne strane otvorenog travnatog brežuljka u uvali. Pokraj špilje prolazi planinarska staza koja vodi za Goljak. Od Velikog Alana voziti po makadamu oko 1,7 km u smjeru Velikog Lubenovca do okuke gdje kreće planinarska staza prema Goljaku. Zatim hodati planinarskom stazom prema Goljaku oko 850 m u smjeru jugoistoka. Jama se nalazi 20m od planinarske staze prema jugu.", "technical_description": "Jednostavan horizontalni speleološki objekt, špilja, pećina. Ulaz je vrlo velik i postoji još jedan vertikalni otvor u stropu špilje. Strop špilje visok je oko 7 m a dno je prekriveno glonđama. Na kraju špilje je penj visine 5m, vjerojatno samo ništavna niša.", "note": null, "literature": null, "name_origin": "smišljeno novo", "synonyms": "LiVEL 166", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1026','da',null,null,'321046;Magični portal;381570.9999999264;4954952.999999895;0.7071067811865476'),
('1608','baza_velebit_2026_apk_sync','Malo gnijezdo',44.7996055036075,14.992479643162,'krug_14',null,'na_provjeri','jama','Ličko-senjska','Senj','Krasno','Veliki Pivčevac, Sjeverni Velebit',12.3,14.5,null,'na_provjeri','{"id": "1608", "source": "sov", "source_labels": ["sov"], "name": "Malo gnijezdo", "location": {"lat": 44.7996055036075, "lon": 14.992479643162, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Veliki Pivčevac, Sjeverni Velebit", "island": null, "altitude_m": 1485.0, "protected_area": null}, "cadastre": {"status": "krug_14", "cadastral_number": null, "in_cadastre": false, "not_in_cadastre_candidate": null}, "classification": {"object_type": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "record_status": "na_provjeri", "field_tasks": [], "priority": null, "kml_export_candidate": true}, "metrics": {"depth_m": 12.3, "length_m": 14.5, "vertical_range_m": 12.3, "entrance_count": 1}, "condition": {"plate_number": "05-1128", "main_entrance_status": null, "hazards": "mogućnost urušavanja ili odrona, krušljive stijene", "pollution": "nema"}, "research": {"last_research_year": 2025, "last_research_date": "2.8.2025", "clubs": "SOV, SOM", "team_members": "Marko Batovanja, Mislav Sajko, Paula Skelin, Lea Okićki, Tomislav Mikić", "survey_author": "Marko Batovanja", "survey_in_digital_base": true, "bibliography_record": null, "georef_record": "321047;Malo gnijezdo;380734.9999999238;4963283.999999889;0.7071067811865476", "further_research_possible": null, "further_research_note": "potpuno istražen"}, "content": {"access_description": "Na makadamu od Lomske dulibe prema Zavižanu, na serpentini s desne strane kilometar prije ulaska na Premužićevu stazu, ulazi se u šumsku vlaku, hoda 400m i skreće se na jug te se dolazi na objekt nakon 50m. U blizini objekta nalazi se objekt Ledeno gnijezdo (05-1187)", "technical_description": "Jednostavni speleološki objekt, dvostruko sidrište na početku i jedno sidrište na pola objekta. Potrebna oprema; uže 30m, gurtna, zamka, 3 karabinera i 1 S pločica. Pripaziti na kamenje i glonđe.", "note": null, "literature": null, "name_origin": "smišljeno novo", "synonyms": null, "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1128','da',null,null,'321047;Malo gnijezdo;380734.9999999238;4963283.999999889;0.7071067811865476'),
('1609','baza_velebit_2026_apk_sync','Mišolovka',44.7643757983679,15.0314198254751,'krug_14',null,'na_provjeri','jama','Ličko-senjska','Senj','Krasno','Hajdučki kukovi, Sjeverni Velebit',60.0,63.1,null,'na_provjeri','{"id": "1609", "source": "sov", "source_labels": ["sov"], "name": "Mišolovka", "location": {"lat": 44.7643757983679, "lon": 15.0314198254751, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Hajdučki kukovi, Sjeverni Velebit", "island": null, "altitude_m": 1476.0, "protected_area": null}, "cadastre": {"status": "krug_14", "cadastral_number": null, "in_cadastre": false, "not_in_cadastre_candidate": null}, "classification": {"object_type": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "record_status": "na_provjeri", "field_tasks": [], "priority": null, "kml_export_candidate": true}, "metrics": {"depth_m": 60.0, "length_m": 63.1, "vertical_range_m": 60.0, "entrance_count": 1}, "condition": {"plate_number": "05-1127", "main_entrance_status": null, "hazards": "nema", "pollution": "nema"}, "research": {"last_research_year": 2025, "last_research_date": "3.8.2025", "clubs": "SOV, SOM, SUE", "team_members": "Dario Mrkonjić, Mia Šepčević, Matea Novosel, Luka Peloza, Hrvoje Đurinski", "survey_author": "Dario Mrkonjić", "survey_in_digital_base": true, "bibliography_record": null, "georef_record": "321048;Mišolovka;383744.99999993306;4959312.999999906;0.7071067811865476", "further_research_possible": null, "further_research_note": "potpuno istražen"}, "content": {"access_description": "Jama se nalazi na SI obroncima Hajdučkih kukova na sjevernom Velebitu. U Krasnom polju se krene glavnom šumskom asfaltiranom cestom prema Velikom Lomu. Dolazi se do raskrižja koje je na oštrom zavoju i skrene se desno u smjeru Zavižana. Na ovom raskrižju se skreće s asfaltirane ceste na makadam koji vodi do Zavižana te je postavljena rampa na ulazu u makadam. Neposredno nakon što se prođe Mali Lom a prije lugarnice na Velikom lomu skrene se u lijevo u šumu (smjer JZ) odnosno prate se oznake koje su postavili speleolozi za put prema Lubuškoj i jami Nedam. STaza se prati cca 400 m, a zatim se skrene prema JZ i hoda još cca 300 m uzbrdo, do ruba stijenjaka. Ulaz u jamu je iznad procjepa u stijenama, nije uočljiv.", "technical_description": "Ulaz jame se nalazi u pukotini, koja je većinom zatrpana glonđama. Jama je jednostavnog vertikalnog oblika i opremljena s 14 fikseva. Za opremanje je potrebno 100m užeta.", "note": "44.764390, 15.031371; 44.764444, 15.031425", "literature": null, "name_origin": "smišljeno novo", "synonyms": "Papi 1", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1127','da',null,null,'321048;Mišolovka;383744.99999993306;4959312.999999906;0.7071067811865476'),
('1610','baza_velebit_2026_apk_sync','Mjesečev meandar',44.7761203568599,15.0307304308206,'krug_14',null,'na_provjeri','špilja','Ličko-senjska','Senj','Krasno','Veliki Rajinac, Sjeverni Velebit',11.7,44.0,null,'na_provjeri','{"id": "1610", "source": "sov", "source_labels": ["sov"], "name": "Mjesečev meandar", "location": {"lat": 44.7761203568599, "lon": 15.0307304308206, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Veliki Rajinac, Sjeverni Velebit", "island": null, "altitude_m": 1400.0, "protected_area": null}, "cadastre": {"status": "krug_14", "cadastral_number": null, "in_cadastre": false, "not_in_cadastre_candidate": null}, "classification": {"object_type": "špilja", "object_type_source": "kml_sjeverni_velebit_2026", "record_status": "na_provjeri", "field_tasks": [], "priority": null, "kml_export_candidate": true}, "metrics": {"depth_m": 11.7, "length_m": 44.0, "vertical_range_m": 12.2, "entrance_count": 1}, "condition": {"plate_number": "05-1178", "main_entrance_status": null, "hazards": "nema", "pollution": "nema"}, "research": {"last_research_year": 2025, "last_research_date": "31.7.2025", "clubs": "SOV", "team_members": "Ema Buljan, Dragana Rajković, Dalibor Paar", "survey_author": "Ema Buljan", "survey_in_digital_base": true, "bibliography_record": null, "georef_record": "321049;Mjesečev meandar;383713.9999999332;4960618.999999906;0.7071067811865476", "further_research_possible": null, "further_research_note": "nastavlja se provlačenjem, potrebno proširivanje"}, "content": {"access_description": "Špilja se nalazi u Lomskoj dulibi na sjevernom Velebitu, na zapadnom obronku Velikog Rajinca. Na makadamskoj cesti auto se parkira između Roguša i Lekčevca na vidljivo ugibalištu sa strane. Krene se u dulibu prema Ledenoj jami, ali umjesto prema jami krene se blago udesno prema brdu. Na najlakšem dijelu skrene se s travnjaka u šumu. Potrebno se dignuti 150 mnv prateći GPS koordinate. Špilja se nalazi ispod stijene u šumi (10 m visoke) i nije ulaz vidljiv iz daljine.", "technical_description": "Ulaz u špilju nalazi se na dnu vrtače i dimenzije je 3 x 3 m. Od ulaza se nastavlja ukoso prema dnu po lišću i trulim drvima. Nakon cca 10 m špilja se odvaja u 2 kanala. Desni se spušta u obliku meandra s koraloidima do trentno najdublje točke špilje. Lijevi kanal ima s lijeve strane manju pukotinu bez perspektive. Taj kanal nastavlja se penjem visine 7 m koji se može slobodno ispenjati. Nakon penja slijedi manje suženje i kanal od 10ak m iz kojeg je suženje odakle puše (visina meandra je malo manje od 0,5 m, potrebno proširiti).", "note": null, "literature": null, "name_origin": "smišljeno novo", "synonyms": null, "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1178','da',null,null,'321049;Mjesečev meandar;383713.9999999332;4960618.999999906;0.7071067811865476'),
