ynonyms": "Bugarka 04", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1213','da',null,null,'321050;Nije duga;383234.99999993166;4959738.999999902;0.7071067811865476'),
