išljeno novo", "synonyms": "Još jedna jama u klekovini", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1212','da',null,null,'321051;Overkill klekača;383211.9999999315;4959786.999999904;0.7071067811865476'),
('1613','baza_velebit_2026_apk_sync','Punjeta',44.7384059949015,15.0066725274674,'krug_14',null,'na_provjeri','jama','Ličko-senjska','Senj','Krasno','Vučjak, Sjeverni Velebit',25.3,35.6,null,'na_provjeri','{"id": "1613", "source": "sov", "source_labels": ["sov"], "name": "Punjeta", "location": {"lat": 44.7384059949015, "lon": 15.0066725274674, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Vučjak, Sjeverni Velebit", "island": null, "altitude_m": 1469.0, "protected_area": null}, "cadastre": {"status": "krug_14", "cadastral_number": null, "in_cadastre": false, "not_in_cadastre_candidate": null}, "classification": {"object_type": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "record_status": "na_provjeri", "field_tasks": [], "priority": null, "kml_export_candidate": true}, "metrics": {"depth_m": 25.3, "length_m": 35.6, "vertical_range_m": 25.3, "entrance_count": 1}, "condition": {"plate_number": "05-1193", "main_entrance_status": null, "hazards": "nema", "pollution": "nema"}, "research": {"last_research_year": 2025, "last_research_date": "3.8.2025", "clubs": "SOV, SUE", "team_members": "Dora Troha, Klara Filakovity, Nino Pintaić, Venio Fabijančić", "survey_author": "Dora Troha", "survey_in_digital_base": true, "bibliography_record": null, "georef_record": "321052;Punjeta;381732.99999992707;4956462.999999896;0.7071067811865476", "further_research_possible": null, "further_research_note": "potpuno istražen"}, "content": {"access_description": "Objekt se nalazi istočno od vrha Vučjak, 110 m od makadamske ceste. Pristup je od Velikog Lubenovca, krenuti makdamskom cestom na jug, koja vodi prema Alanu, otprilike 600m azimutom 256°. Nakon toga krenuti uzbrdo 110 m na zapad. Jama se nalazi u blizini manjeg brda, kod njenog vrha na otprilike 10 mnv.", "technical_description": "Jednostavan speleološki objekt dim. otvora 5x12 m. Jednostavan ulaz uz jedno prirodno sidrište i dvostruko sidrište s kojeg se pristupa na dno. Dno objekta prekriveno kamenjem i umusom uz snijegom koji je u najvišem dijelu bio 1,5m.", "note": null, "literature": null, "name_origin": "smišljeno novo", "synonyms": "LiVEL 128", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1193','da',null,null,'321052;Punjeta;381732.99999992707;4956462.999999896;0.7071067811865476'),
('1614','baza_velebit_2026_apk_sync','Puževa smrt',44.7692699763681,15.0411246060445,'krug_14',null,'na_provjeri','jama','Ličko-senjska','Senj','Krasno','Mali Lom, Sjeverni Velebit',40.0,43.0,null,'na_provjeri','{"id": "1614", "source": "sov", "source_labels": ["sov"], "name": "Puževa smrt", "location": {"lat": 44.7692699763681, "lon": 15.0411246060445, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Mali Lom, Sjeverni Velebit", "island": null, "altitude_m": 1315.0, "protected_area": null}, "cadastre": {"status": "krug_14", "cadastral_number": null, "in_cadastre": false, "not_in_cadastre_candidate": null}, "classification": {"object_type": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "record_status": "na_provjeri", "field_tasks": [], "priority": null, "kml_export_candidate": true}, "metrics": {"depth_m": 40.0, "length_m": 43.0, "vertical_range_m": 40.0, "entrance_count": 1}, "condition": {"plate_number": "05-1205", "main_entrance_status": null, "hazards": "nema", "pollution": "nema"}, "research": {"last_research_year": 2025, "last_research_date": "2.8.2025", "clubs": "SOV, SOL, SUE, ASAK", "team_members": "Mateja Dimitrijević, Luka Bogdanić, Marko Ličko, Jakov Rešetar, Lovel Kukuljan, Marina Grandić", "survey_author": "Lovel Kukuljan", "survey_in_digital_base": true, "bibliography_record": null, "georef_record": "321053;Puževa smrt;384522.9999999355;4959842.99999991;0.7071067811865476", "further_research_possible": null, "further_research_note": "potpuno istražen"}, "content": {"access_description": "Makadamskom cestom od Velikog Loma ići prema Malom Lomu. Voziti 10 minutam proći prvi veći zavoj koji se uspinje i onda kad se ponovno počinje spuštati parkirati na proširenju. Hodati 60m od makadama do jame kroz šumu.", "technical_description": "Jama se nalazi na škrapovitom terenu. Jedna od škrapi se otvara u kružnu vertikalu 6m dubine. Na SI rubu se vertikala sužava na uži prolaz dalje 15m dublje do police koja dijeli jamu u dvije paralelne vertikale od 21, odnosno 19m. Ova dublja se otvara u prostor 5 x 2. 2m prije dna se plića vertikala spaja na dublju. Dno je prekriveno blatom i glonđama. Nema perspektive.", "note": null, "literature": null, "name_origin": "smišljeno novo", "synonyms": "LiVEL 193", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1205','da',null,null,'321053;Puževa smrt;384522.9999999355;4959842.99999991;0.7071067811865476'),
