objekt. Ulaz je vrlo uzak procjep ispunjen klimavim glonđama (potrebno je prokopati glonđe za lakši ulaz), zatim se ulazi u 20m vertikalu koja vodi direktno do dna jame prekrivenog kamenjem.", "note": null, "literature": null, "name_origin": "smišljeno novo", "synonyms": "LiVEL 174", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1124','da',null,null,'321059;Uske muke;381643.9999999268;4955073.999999895;0.7071067811865476'),
