ms": "LiVEL 43", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1198','da',null,null,'321060;Utješna;383129.9999999313;4959359.999999902;7.0710678118654755'),
('1623','baza_velebit_2026_apk_sync','Zzzzzz',44.7635662471293,15.0469274188197,'krug_14',null,'na_provjeri','jama','Ličko-senjska','Senj','Krasno','Mali Lom, Sjeverni Velebit',9.0,14.4,null,'na_provjeri','{"id": "1623", "source": "sov", "source_labels": ["sov"], "name": "Zzzzzz", "location": {"lat": 44.7635662471293, "lon": 15.0469274188197, "county": "Ličko-senjska", "municipality": "Senj", "nearest_place": "Krasno", "locality": "Mali Lom, Sjeverni Velebit", "island": null, "altitude_m": 1242.0, "protected_area": null}, "cadastre": {"status": "krug_14", "cadastral_number": null, "in_cadastre": false, "not_in_cadastre_candidate": null}, "classification": {"object_type": "jama", "object_type_source": "kml_sjeverni_velebit_2026", "record_status": "na_provjeri", "field_tasks": [], "priority": null, "kml_export_candidate": true}, "metrics": {"depth_m": 9.0, "length_m": 14.4, "vertical_range_m": 9.0, "entrance_count": 1}, "condition": {"plate_number": "05-1170", "main_entrance_status": null, "hazards": "nema", "pollution": "nema"}, "research": {"last_research_year": 2025, "last_research_date": "28.7.2025", "clubs": "SOV, SOL", "team_members": "Luka Bogdanić, Nino Pintarić, Ivona Klišanin", "survey_author": "Luka Bogdanić", "survey_in_digital_base": true, "bibliography_record": null, "georef_record": "321061;Zzzzzz;384970.99999993667;4959200.999999911;0.7071067811865476", "further_research_possible": null, "further_research_note": "potpuno istražen"}, "content": {"access_description": "Jama se nalazi na sjeveroistočnim obroncima Golubića na Sjevernom Velebitu. Od rampe ići makadamom u smjeru sjeverozapada 30 m do lugarnice na Malom Lomu. Od lugarnice kretati se zaraslom starom šumskom vlakom 450 m. Zatim ići direktno preko vrtače u smjeru sjeverozapada 440 m.", "technical_description": "Jama ima 2 ulaza. Preko kosine od 3 metra se dolazi do skoka od 2 metra gdje se postavlja umjetno sidrište preko kojeg se spušta u zaglonanu kosinu sve do skoka od 1 metar, gdje se nalazi dno puno komaraca. Za opremanje je potrebno 20 m ueta, 1 gurtna i 1 sidrišni komplet.", "note": null, "literature": null, "name_origin": "smišljeno novo", "synonyms": "LiVEL 118", "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,'05-1170','da',null,null,'321061;Zzzzzz;384970.99999993667;4959200.999999911;0.7071067811865476'),
