('1724','baza_velebit_2026_apk_sync','CR_PR_1',44.7533414117229,14.9831623919245,'nije_u_katastru',null,'nije_u_katastru',null,'Ličko-senjska',null,null,null,null,null,'istraziti','nije_u_katastru','{"id": "1724", "source": "sov", "source_labels": ["sov"], "name": "CR_PR_1", "location": {"lat": 44.7533414117229, "lon": 14.9831623919245, "county": "Ličko-senjska", "municipality": null, "nearest_place": null, "locality": null, "island": null, "altitude_m": 1481.0, "protected_area": null}, "cadastre": {"status": "nije_u_katastru", "cadastral_number": null, "in_cadastre": false, "not_in_cadastre_candidate": null}, "classification": {"object_type": null, "object_type_source": null, "record_status": "nije_u_katastru", "field_tasks": ["istraziti"], "priority": null, "kml_export_candidate": true}, "metrics": {"depth_m": null, "length_m": null, "vertical_range_m": null, "entrance_count": null}, "condition": {"plate_number": null, "main_entrance_status": null, "hazards": null, "pollution": null}, "research": {"last_research_year": null, "last_research_date": null, "clubs": null, "team_members": null, "survey_author": null, "survey_in_digital_base": false, "bibliography_record": null, "georef_record": null, "further_research_possible": null, "further_research_note": null}, "content": {"access_description": null, "technical_description": null, "note": "1. About 10-12m deep hole (according to dropped stones), close to the southern side of a small but very steep dolina, to the southwest from Cirkvena. The entrance is about 1.2m x 2.0m. It needs at least a little rope do go down, not a safe climb, so we did not manage to check the bottom. 2. Located 1.1 km to the southwest from Cirkvena peak. The entrance is climbable, after about 5-6m downclimb, there is a ~4x6m room. We did not have time to map it, so it has no cataster number yet. 3. About 120m away from Clover cave to the north. It is probably formed on the same crack. It is divided into two part. First there is a climbable 4m drop, then another narrower 5-6m into the crack. Then it continues, but very tight.", "literature": null, "name_origin": null, "synonyms": null, "other_synonyms": null, "clean_cave_report": null, "geological_or_anthropogenic_activities": null}, "raw": {"workflow_raw": "kml_sjeverni_velebit_2026", "katastar_id": null, "katastar_coordinate_source": null, "katastar_coordinate_uncertainty_m": null}, "search_text": null}'::jsonb,'apk_bundle_sync_20260721',now(),now(),'Uvezeno iz APK baze (baza_velebit_2026_android_v2) 2026-07-21','staging','apk-sync',now(),false,null,null,null,null,null),
