-- =====================================================================
-- SOV — sinkronizacija baze objekata: APK bundle -> Supabase
-- Datum: 2026-07-21
-- Dodaje 293 objekta (source_id 1585..1877) koji postoje u APK bazi
-- (baza_velebit_2026_android_v2.json.gz) ali su falili na webu.
--
-- Backup je VEC napravljen migracijom sov_objects_sync_backup_20260721:
--   speleo_objects_staging_backup_20260721
--   speleo_objects_live_sql_backup_20260721
--
-- Sigurno za ponovno pokretanje (ON CONFLICT DO NOTHING).
-- ROLLBACK: delete from speleo_objects_staging where import_batch='apk_bundle_sync_20260721';
--           delete from speleo_objects_live_sql where promoted_by='apk_sync_20260721';
-- =====================================================================
begin;

on conflict (source_id) do nothing;

-- Promocija istih redaka u live_sql (koristi ga arhivar/izvoz)
   object_type_final, county, municipality, nearest_place, locality, depth_m, length_m,
   field_tasks, workflow_raw, edit_note, raw, promoted_from_staging_at, promoted_by,
   promotion_batch_id, updated_at)
select s.source_id, s.source_system, s.name, s.lat, s.lon, s.cadastre_status, s.cadastral_number,
       s.record_status, s.object_type_final, s.county, s.municipality, s.nearest_place, s.locality,
       s.depth_m, s.length_m, s.field_tasks, s.workflow_raw, s.edit_note, s.raw,
       now(), 'apk_sync_20260721', null, now()
from public.speleo_objects_staging s
where s.import_batch = 'apk_bundle_sync_20260721'
on conflict (source_id) do nothing;

commit;

-- Provjera nakon pokretanja (ocekivano: staging 1578, live_sql 1578, karta 1578)
select 'staging' t, count(*) n from public.speleo_objects_staging
union all select 'live_sql', count(*) from public.speleo_objects_live_sql
union all select 'karta (sov_map_objects_light)', count(*) from public.sov_map_objects_light;
